-- Challan PDFs are generated when a sale is saved or edited (or regenerated by an admin) and stored.
-- Older PDFs are kept. snapshot holds the exact data the PDF was drawn from (all sites), so a coordinator
-- copy can be drawn from the same frozen data with only their own sites.
create table sale_challans (
  id bigserial primary key,
  sale_id bigint not null references sales(id) on delete cascade,
  seq int not null,
  reason varchar(12) not null check (reason in ('CREATED','EDITED','REGENERATED','BACKFILL')),
  created_at timestamptz not null default now(),
  created_by bigint,
  pdf bytea not null,
  snapshot jsonb not null,
  unique (sale_id, seq)
);
